package com.zerotrust.internalresource.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="device_resources") public class DeviceResourceEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String resourceId; private String deviceName; private String ipAddress; private String deviceType; private String location; private String department; private String securityLevel; private String status; private Instant lastHeartbeat; private Instant createdAt; private Instant updatedAt; protected DeviceResourceEntity(){} public Long getId(){return id;} public String getResourceId(){return resourceId;} public void setResourceId(String v){resourceId=v;} public String getDeviceName(){return deviceName;} public void setDeviceName(String v){deviceName=v;} public String getIpAddress(){return ipAddress;} public void setIpAddress(String v){ipAddress=v;} public String getDeviceType(){return deviceType;} public void setDeviceType(String v){deviceType=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getSecurityLevel(){return securityLevel;} public void setSecurityLevel(String v){securityLevel=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getLastHeartbeat(){return lastHeartbeat;} public void setLastHeartbeat(Instant v){lastHeartbeat=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }